WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY page, event_type ORDER BY duration_sec, id) AS rank_in_group FROM web_events QUALIFY rank_in_group = 1) SELECT DATE_TRUNC('MONTH', event_time) AS activity_month, CASE WHEN duration_sec >= 461 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, MAX(event_time) AS last_event_time, BIT_OR(duration_sec) AS duration_sec_bit_or, COUNT(*) AS row_count, AVG(duration_sec) AS avg_duration_sec, STDDEV_SAMP(duration_sec) AS duration_sec_stddev FROM ranked GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', event_time), CASE WHEN duration_sec >= 461 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('MONTH', event_time)), ())
